  public static double Angle(double position,double primary) {
   double l=Numbers.Clamp(primary,0,1)*20,r=Numbers.Clamp(position,0,1)*100;
   int a=Math.Min(19,(int)l),b=Math.Min(99,(int)r);double f=l-a,g=r-b;
   return (Angles[a,b]*(1-g)+Angles[a,b+1]*g)*(1-f)+(Angles[a+1,b]*(1-g)+Angles[a+1,b+1]*g)*f;
  }
  public static double Position(double degrees,double primary) {
   if(!Numbers.Finite(degrees)||!Numbers.Finite(primary))throw new ArgumentException("Invalid roll mapping");
   double lo=0,hi=1;
   if(degrees>=Angle(lo,primary))return lo;
   if(degrees<=Angle(hi,primary))return hi;
   for(int i=0;i<24;i++){double m=(lo+hi)*.5;if(Angle(m,primary)>degrees)lo=m;else hi=m;}
   return (lo+hi)*.5;
  }
